/* @lc app=leetcode id=2286 lang=kotlin */ class BookMyShow(val n: Int, val m: Int, val sz: Int = generateSequence(1) { it * 2 }.first { it > n }, val mx: IntArray = IntArray(2 * sz).also { a -> (0 until n).forEach { a[sz + it] = m } }, val sm: LongArray = LongArray(2 * sz).also { a -> (0 until n).forEach { a[sz + it] = m.toLong() } }, val init: Unit = (sz - 1 downTo 1).forEach { i -> mx.set(i, maxOf(mx[2 * i], mx[2 * i + 1])).also { sm[i] = sm[2 * i] + sm[2 * i + 1] } }) { fun pull(i: Int) = mx.set(i, maxOf(mx[2 * i], mx[2 * i + 1])).also { sm[i] = sm[2 * i] + sm[2 * i + 1] } fun upd(row: Int, v: Int) = mx.set(sz + row, v).also { sm[sz + row] = v.toLong() }.also { generateSequence((sz + row) / 2) { it / 2 }.takeWhile { it >= 1 }.forEach { pull(it) } } fun first(k: Int): Int = if (mx[1] < k) -1 else generateSequence(1) { i -> if (i >= sz) null else if (mx[2 * i] >= k) 2 * i else 2 * i + 1 }.last() - sz fun gather(k: Int, maxRow: Int): IntArray = first(k).let { r -> if (r < 0 || r > maxRow) intArrayOf() else (m - mx[sz + r]).let { c -> intArrayOf(r, c).also { upd(r, mx[sz + r] - k) } } } fun scatter(k: Int, maxRow: Int): Boolean = generateSequence(maxRow + 1 + sz) { it / 2 }.takeWhile { it > 1 }.sumOf { x -> if (x % 2 == 1) sm[x - 1] else 0L } >= k && true.also { generateSequence(k to first(1)) { (rem, row) -> if (rem == 0) null else minOf(rem, mx[sz + row]).let { t -> upd(row, mx[sz + row] - t).let { (rem - t) to row + 1 } } }.count() } }